styles:
:root{--dark:#0c0c0e;--dark2:#161619;--cream:#eeeae3;--ink:#181719;--white:#f6f3ee;--line-light:rgba(255,255,255,.19);--line-dark:rgba(0,0,0,.2);--red:#e81848;--muted-light:#b6b3b1;--muted-dark:#585657;--pad:clamp(22px,5vw,88px);--content:1560px;--ease:cubic-bezier(.22,1,.36,1)}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:84px}body{margin:0;background:var(--dark);color:var(--white);font-family:Arial,"Helvetica Neue",Helvetica,sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}body.menu-open{overflow:hidden}img{display:block;width:100%;height:auto}button,input{font:inherit}a{color:inherit;text-decoration:none}a:focus-visible,button:focus-visible{outline:2px solid var(--red);outline-offset:5px}.container{width:min(100% - 2*var(--pad),var(--content));margin-inline:auto}.skip{position:fixed;z-index:1000;top:-150px;left:10px;background:white;color:black;padding:15px}.skip:focus{top:10px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
.mono,.eyebrow,.section-label,.meta,.nav-links,.nav-action,.text-link,.card-number,.project-num,.index-label,.footer-meta,.hero-note,.process-id,.industry-row span{font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:.125em;line-height:1.45;text-transform:uppercase;font-weight:700}.eyebrow{display:flex;align-items:center;gap:12px}.eyebrow::before{content:"";display:block;width:22px;height:2px;background:var(--red)}.section-label{color:var(--muted-dark)}.section-label.on-dark{color:#beb9ba}.label-line{padding-bottom:17px;border-bottom:1px solid currentColor;opacity:.8}.arrow{display:inline-block;transition:transform .3s var(--ease)}a:hover .arrow{transform:translate(3px,-3px)}.text-link{display:inline-flex;align-items:center;gap:17px;padding:13px 0;border-bottom:1px solid currentColor;letter-spacing:.09em}.text-link:hover{color:var(--red)}.manifesto .text-link:hover,.projects .text-link:hover,.process .text-link:hover{color:#ad0b36}
/* Navigation */
.site-header{position:sticky;top:0;z-index:50;background:rgba(12,12,14,.96);backdrop-filter:blur(14px);border-bottom:1px solid var(--line-light)}.nav{display:flex;align-items:center;justify-content:space-between;gap:30px;min-height:82px}.logo{display:block;flex-shrink:0;width:148px}.logo img{width:100%;height:auto}.nav-links{display:flex;align-items:center;gap:clamp(18px,2vw,36px);letter-spacing:.08em}.nav-links a{position:relative;color:#e0dcda;white-space:nowrap}.nav-links a:after{content:"";position:absolute;left:0;right:100%;bottom:-7px;border-bottom:1px solid var(--red);transition:right .25s}.nav-links a:hover:after{right:0}.nav-action{display:flex;gap:15px;align-items:center;background:var(--red);padding:13px 17px;letter-spacing:.06em;white-space:nowrap;transition:background .25s}.nav-action:hover{background:#c9143c}.menu-btn{display:none;border:1px solid var(--line-light);background:none;color:#fff;width:45px;height:45px;align-items:center;justify-content:center;cursor:pointer}.menu-btn span{width:20px;height:2px;background:white;position:relative;display:block}.menu-btn span:before,.menu-btn span:after{content:"";width:20px;height:2px;background:white;position:absolute;left:0}.menu-btn span:before{top:-6px}.menu-btn span:after{top:6px}.mobile-nav{display:none}
/* Hero */
.hero{padding-top:clamp(65px,8vw,132px);padding-bottom:clamp(52px,6vw,92px)}.hero-overline{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-bottom:25px;border-bottom:1px solid var(--line-light)}.hero-overline .eyebrow{color:#d4d0ce}.hero-overline .mono{color:#a9a5a5}.hero-top{display:grid;grid-template-columns:1.65fr .58fr;gap:70px;align-items:end;padding:42px 0 clamp(45px,6vw,94px)}.hero h1{font-weight:600;line-height:.91;letter-spacing:-.077em;font-size:clamp(70px,8.85vw,166px);max-width:1250px;margin:0}.hero h1 em{font-style:normal;color:var(--red)}.hero h1 .h-last{white-space:nowrap}.hero-aside{padding-bottom:9px}.hero-aside p{font-size:clamp(16px,1.27vw,21px);line-height:1.53;max-width:350px;margin:0 0 30px;color:#d7d1cf}.hero-actions{display:flex;flex-wrap:wrap;gap:18px;align-items:center}.btn-primary{display:inline-flex;gap:30px;align-items:center;justify-content:space-between;background:var(--red);padding:17px 19px;min-height:50px;font-weight:700;font-size:13px;transition:background .25s}.btn-primary:hover{background:#c9143c}.btn-quiet{display:inline-flex;gap:13px;font-size:13px;padding:14px 0;border-bottom:1px solid #8d8989}.btn-quiet:hover{color:var(--red)}.hero-photo{margin:0;position:relative;height:clamp(350px,45vw,650px);overflow:hidden;background:#381f1f}.hero-photo img{height:100%;object-fit:cover;object-position:center 47%}.photo-index{position:absolute;display:flex;justify-content:space-between;align-items:center;gap:15px;bottom:0;left:0;right:0;padding:18px 22px;color:white;background:linear-gradient(0deg,rgba(0,0,0,.74),transparent);font-size:11px;letter-spacing:.09em;text-transform:uppercase;font-weight:700}.photo-index strong{font-size:12px}.hero-bottom{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:21px;color:#a9a4a3}.hero-bottom p{margin:0;font-size:12px;line-height:1.5;letter-spacing:.02em}.hero-bottom p:last-child{text-align:right}
/* Shared sections */
.section{padding-block:clamp(100px,11vw,175px)}.lead-title{font-size:clamp(49px,6.1vw,112px);line-height:.97;letter-spacing:-.069em;font-weight:600;margin:0}.lead-title strong{font-weight:inherit;color:var(--red)}.section-head{display:grid;grid-template-columns:1fr 3fr;gap:25px;margin-bottom:70px;align-items:start}.section-head .section-label{padding-top:10px}.section-intro{font-size:clamp(17px,1.45vw,22px);line-height:1.58;max-width:620px;color:#686364}.section-head .section-intro{margin:25px 0 0}.on-dark .section-intro{color:#b2adae}
/* Editorial manifesto */
.manifesto{background:var(--cream);color:var(--ink)}.manifesto-grid{display:grid;grid-template-columns:1.05fr 1.15fr;gap:clamp(35px,7vw,120px);align-items:center}.manifesto h2{font-size:clamp(58px,6.4vw,120px);letter-spacing:-.072em;line-height:.98;margin:36px 0 30px;font-weight:600}.manifesto h2 span{color:var(--red)}.manifesto p{font-size:clamp(17px,1.45vw,22px);line-height:1.6;max-width:590px;color:#595557}.manifesto-media{position:relative;display:grid;grid-template-columns:.7fr 1fr;align-items:end;gap:20px;min-width:0}.manifesto-media figure{margin:0;min-width:0}.manifesto-media img{object-fit:cover}.manifesto-media figure:first-child img{aspect-ratio:3/4;object-position:37% center}.manifesto-media figure:nth-child(2){padding-bottom:65px}.manifesto-media figure:nth-child(2) img{aspect-ratio:4/5;object-position:55% center}.manifesto-media figcaption{border-top:1px solid var(--line-dark);padding-top:14px;margin-top:13px;color:#5a5556;letter-spacing:.08em;font-size:10px;text-transform:uppercase;font-weight:700}.principles{border-top:1px solid var(--line-dark);margin-top:clamp(58px,6vw,100px);display:grid;grid-template-columns:repeat(3,1fr)}.principle{padding:28px 30px 0 0;display:flex;flex-direction:column;gap:12px}.principle:not(:last-child){border-right:1px solid var(--line-dark);margin-right:30px}.principle span{font-size:11px;color:#555052;letter-spacing:.1em}.principle strong{font-size:clamp(20px,2vw,30px);line-height:1.15;letter-spacing:-.04em;font-weight:600}.principle p{font-size:14px;line-height:1.5;color:#686363;margin:0}
/* Services */
.services{background:var(--dark)}.services .section-head{margin-bottom:68px}.services .section-intro{color:#aaa6a8}.service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-top:1px solid var(--line-light);border-left:1px solid var(--line-light)}.service-card{min-width:0;padding:clamp(22px,3vw,44px);border-right:1px solid var(--line-light);border-bottom:1px solid var(--line-light);display:flex;flex-direction:column}.service-top{display:flex;justify-content:space-between;gap:20px;margin-bottom:25px}.service-top .mono{color:#a9a5a5}.service-top span:last-child{font-size:11px;letter-spacing:.1em;color:#9e9999}.service-card h3{font-size:clamp(34px,3.6vw,64px);letter-spacing:-.06em;line-height:1.04;font-weight:600;margin:0 0 24px}.service-card img{aspect-ratio:16/9;object-fit:cover;object-position:left top;border:1px solid #333;width:100%;background:#19191c}.service-card p{color:#bcb5b4;font-size:16px;line-height:1.65;max-width:590px;margin:26px 0 18px}.service-card .text-link{margin-top:auto;align-self:start}
/* Projects */
.projects{background:var(--cream);color:var(--ink)}.projects .section-head{margin-bottom:70px}.project-list{border-top:1px solid var(--line-dark)}.project-item{display:grid;grid-template-columns:100px 1.45fr 1fr;gap:clamp(20px,4vw,65px);padding:clamp(45px,6vw,85px) 0;border-bottom:1px solid var(--line-dark);align-items:start}.project-item .project-num{color:#575254;padding-top:15px}.project-media{overflow:hidden;background:#ddd8d1;min-width:0}.project-media img{aspect-ratio:16/10;object-fit:cover;transition:transform .8s var(--ease)}.project-item:hover .project-media img{transform:scale(1.028)}.project-content{padding-top:10px}.project-content .meta{display:block;color:#575254;margin-bottom:35px}.project-content h3{font-size:clamp(34px,3.5vw,60px);line-height:1.04;letter-spacing:-.06em;font-weight:600;margin:0 0 20px}.project-content p{font-size:16px;line-height:1.65;color:#5c5758;margin-bottom:28px}.project-bottom{display:flex;justify-content:flex-end;margin-top:38px}
/* AI */
.ai-section{background:#18171a;overflow:hidden}.ai-layout{display:grid;grid-template-columns:1.05fr 1fr;gap:clamp(50px,10vw,160px);align-items:start}.ai-section h2{font-size:clamp(58px,6vw,108px);line-height:.99;letter-spacing:-.072em;font-weight:600;margin:32px 0}.ai-section h2 em{font-style:normal;color:var(--red)}.ai-description{max-width:555px;font-size:19px;line-height:1.6;color:#c0b9b9;margin:0 0 25px}.ai-points{border-top:1px solid var(--line-light);margin-top:50px}.ai-point{display:grid;grid-template-columns:38px 1fr;gap:22px;border-bottom:1px solid var(--line-light);padding:31px 0}.ai-point .mono{color:var(--red);padding-top:6px}.ai-point h3{font-size:clamp(22px,2.2vw,34px);letter-spacing:-.04em;margin:0 0 8px;font-weight:600}.ai-point p{color:#aaa4a4;font-size:15px;line-height:1.55;margin:0}
/* Process and industry */
.process{background:var(--cream);color:var(--ink)}.process-grid{display:grid;grid-template-columns:1fr 1.35fr;gap:clamp(65px,9vw,170px)}.process h2{font-size:clamp(48px,5.3vw,100px);font-weight:600;line-height:.99;letter-spacing:-.068em;margin:30px 0}.process .section-intro{margin-bottom:34px}.steps{border-top:1px solid var(--line-dark)}.step{display:grid;grid-template-columns:55px 1fr;gap:25px;padding:22px 0;border-bottom:1px solid var(--line-dark)}.step .process-id{color:#575254;padding-top:6px}.step h3{font-size:clamp(26px,2.55vw,40px);letter-spacing:-.04em;margin:0 0 6px;font-weight:600}.step p{font-size:15px;line-height:1.52;color:#595455;margin:0}.industries{margin-top:clamp(85px,9vw,155px);padding-top:35px;border-top:1px solid var(--line-dark);display:grid;grid-template-columns:1fr 2fr;gap:40px}.industries h3{font-size:clamp(25px,2.9vw,45px);line-height:1.1;letter-spacing:-.045em;margin:0;font-weight:600}.industry-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 30px}.industry-row{padding:17px 0;border-bottom:1px solid var(--line-dark);font-size:19px;display:flex;justify-content:space-between;gap:12px}.industry-row span{font-size:11px;color:#575254;white-space:nowrap;align-self:center}
/* Team */
.team{background:var(--dark);color:var(--white)}.team-intro{display:grid;grid-template-columns:.8fr 1.25fr;gap:70px;margin-bottom:60px}.team h2{font-size:clamp(52px,6.4vw,120px);line-height:.99;letter-spacing:-.072em;font-weight:600;margin:24px 0 0}.team-intro p{font-size:clamp(18px,1.6vw,24px);line-height:1.58;color:#c0b9b7;margin:34px 0 0;max-width:600px}.people{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(22px,3vw,50px)}.person{min-width:0;margin:0}.person img{aspect-ratio:4/5;object-fit:cover;object-position:50% 31%;filter:saturate(.82)}.person figcaption{display:grid;grid-template-columns:1fr 1fr;gap:20px;border-top:1px solid var(--line-light);padding-top:21px;margin-top:17px}.person strong{font-size:clamp(23px,2.1vw,34px);letter-spacing:-.045em;font-weight:600}.person span{font-size:12px;line-height:1.55;color:#bcb6b5;padding-top:5px}.team-tail{display:flex;align-items:center;justify-content:space-between;gap:30px;margin-top:55px}.team-tail p{max-width:480px;color:#aba4a3;font-size:16px;line-height:1.6}
/* Final and footer */
.final{background:var(--red);padding:clamp(70px,8vw,135px) 0;color:white}.final-head{display:grid;grid-template-columns:1fr 2fr;gap:40px;align-items:start}.final .eyebrow:before{background:white}.final h2{font-size:clamp(64px,9.8vw,176px);line-height:.91;letter-spacing:-.076em;font-weight:600;margin:0 0 50px;max-width:1250px}.final-bottom{border-top:1px solid rgba(255,255,255,.6);padding-top:27px;display:flex;gap:40px;justify-content:space-between;align-items:end}.final p{max-width:540px;margin:0;font-size:18px;line-height:1.55}.final-link{display:inline-flex;align-items:center;justify-content:space-between;gap:90px;font-weight:700;background:white;color:var(--ink);font-size:14px;padding:19px 22px}.final-link:hover{background:#ece7e2}.footer{background:#080809;padding:75px 0 32px}.footer-upper{display:grid;grid-template-columns:1.3fr repeat(3,1fr);gap:clamp(30px,4vw,70px);padding-bottom:95px}.footer-brand img{width:195px}.footer-brand p{font-size:15px;color:#aaa4a2;line-height:1.58;max-width:300px;margin-top:30px}.footer-col h3{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:#9a9291;margin:0 0 25px;font-weight:700}.footer-col a{display:block;width:fit-content;color:#e2dbd8;font-size:14px;padding:7px 0;line-height:1.6}.footer-col a:hover{color:#f64b70}.footer-meta{border-top:1px solid var(--line-light);padding-top:24px;display:flex;justify-content:space-between;gap:15px;color:#9e9897;letter-spacing:.06em}
@media(max-width:1180px){.nav-links{gap:16px}.nav-links a{font-size:10px}.hero-top{grid-template-columns:1.2fr .65fr;gap:30px}.hero h1{font-size:clamp(60px,8.3vw,105px)}.project-item{grid-template-columns:45px 1.25fr 1fr;gap:25px}.process-grid{gap:55px}}
@media(max-width:900px){:root{--pad:clamp(22px,4.5vw,43px)}.nav{min-height:74px}.nav-links,.nav .nav-action{display:none}.menu-btn{display:flex}.mobile-nav{display:block;position:fixed;inset:74px 0 0;z-index:45;background:#0c0c0e;padding:40px var(--pad);visibility:hidden;opacity:0;transform:translateY(-8px);transition:opacity .25s,transform .25s,visibility .25s;overflow:auto}.mobile-nav.open{visibility:visible;opacity:1;transform:none}.mobile-nav a{display:flex;justify-content:space-between;padding:18px 0;border-bottom:1px solid var(--line-light);font-size:clamp(29px,5vw,48px);line-height:1;letter-spacing:-.04em}.mobile-nav .mobile-cta{background:var(--red);margin-top:25px;padding:17px 19px;font-size:17px;font-weight:700}.hero-top{grid-template-columns:1fr;gap:28px}.hero h1{font-size:clamp(58px,11.1vw,100px)}.hero-aside{display:flex;align-items:end;justify-content:space-between;gap:25px}.hero-aside p{margin:0;max-width:390px}.hero-actions{flex-direction:column;align-items:flex-start}.hero-photo{height:clamp(310px,50vw,540px)}.section-head{grid-template-columns:1fr 2.6fr}.manifesto-grid{grid-template-columns:1fr 1fr;gap:30px}.manifesto h2{font-size:clamp(49px,6vw,76px)}.manifesto-media{grid-template-columns:1fr}.manifesto-media figure:first-child{display:none}.manifesto-media figure:nth-child(2){padding:0}.manifesto-media figure:nth-child(2) img{aspect-ratio:3/4}.project-item{grid-template-columns:40px 1fr;gap:20px}.project-media{grid-column:2;grid-row:1}.project-content{grid-column:2;grid-row:2}.project-num{grid-row:1}.project-content .meta{margin-bottom:18px}.process-grid{grid-template-columns:1fr}.process-heading{max-width:590px}.steps{margin-top:20px}.team-intro{grid-template-columns:1fr 1.2fr;gap:40px}.footer-upper{grid-template-columns:1.5fr 1fr 1fr}.footer-col:last-child{grid-column:2/4}.footer-col:last-child a{display:inline-block;margin-right:16px}}
@media(max-width:900px){.industries{grid-template-columns:1fr}.industry-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.industry-row{font-size:16px}.industry-row span{font-size:11px}}
@media(max-width:650px){:root{--pad:21px}.nav{min-height:67px}.site-header .logo{width:132px}.mobile-nav{top:67px}.hero{padding-top:52px;padding-bottom:62px}.hero-overline{padding-bottom:19px}.hero-overline .mono{display:none}.eyebrow{font-size:10px;letter-spacing:.1em}.hero-top{padding:34px 0 37px}.hero h1{font-size:clamp(54px,12.7vw,81px);letter-spacing:-.071em;line-height:.94}.hero h1 .h-last{white-space:normal}.hero-aside{display:block}.hero-aside p{font-size:17px;line-height:1.5;max-width:480px;margin-bottom:25px}.hero-actions{flex-direction:row;gap:16px;align-items:center}.btn-primary{font-size:12px;padding:16px;gap:15px}.btn-quiet{font-size:12px}.hero-photo{height:clamp(310px,96vw,475px)}.hero-photo img{object-position:50% 50%}.photo-index{padding:15px 13px;font-size:11px}.photo-index strong{font-size:10px}.hero-bottom{grid-template-columns:1fr 1fr;gap:15px}.hero-bottom p{font-size:10px}.hero-bottom p:last-child{display:none}.section{padding-block:90px}.section-head{display:block;margin-bottom:40px}.section-head .section-label{display:block;margin-bottom:29px}.lead-title{font-size:clamp(48px,11vw,70px)}.section-intro{font-size:17px;line-height:1.6}.section-head .section-intro{margin-top:24px}.manifesto-grid{grid-template-columns:1fr}.manifesto h2{font-size:clamp(52px,11.1vw,73px);margin:28px 0 22px}.manifesto p{font-size:17px}.manifesto-media{grid-template-columns:1fr 1fr;gap:12px;align-items:end}.manifesto-media figure:first-child{display:block}.manifesto-media figure:nth-child(2){padding-bottom:30px}.manifesto-media figure:first-child img{aspect-ratio:4/5}.manifesto-media figure:nth-child(2) img{aspect-ratio:3/4}.manifesto-media figcaption{font-size:11px}.principles{grid-template-columns:1fr;margin-top:50px}.principle{margin:0!important;border-right:none!important;border-bottom:1px solid var(--line-dark);padding:23px 0}.principle strong{font-size:24px}.principle p{font-size:15px}.services .section-head{margin-bottom:38px}.service-grid{grid-template-columns:1fr}.service-card{padding:25px 20px 35px}.service-card h3{font-size:45px}.service-card p{font-size:16px}.project-item{grid-template-columns:1fr;gap:0;padding:44px 0}.project-num{grid-row:auto;grid-column:1;padding:0 0 16px}.project-media{grid-column:1;grid-row:auto}.project-media img{aspect-ratio:4/3}.project-content{grid-column:1;grid-row:auto;padding-top:24px}.project-content h3{font-size:39px}.project-content p{font-size:16px;margin-bottom:12px}.project-content .meta{margin-bottom:15px}.project-bottom{justify-content:flex-start}.ai-layout{grid-template-columns:1fr;gap:20px}.ai-section h2{font-size:clamp(54px,11.5vw,78px)}.ai-description{font-size:17px}.ai-points{margin-top:12px}.ai-point{padding:20px 0}.process h2{font-size:clamp(52px,11vw,76px)}.steps{margin-top:0}.step h3{font-size:29px}.industries{display:block;margin-top:80px}.industries h3{margin-bottom:25px}.industry-grid{grid-template-columns:1fr}.industry-row{font-size:18px}.team-intro{display:block;margin-bottom:38px}.team h2{font-size:clamp(52px,11.5vw,78px)}.team-intro p{font-size:17px;margin-top:24px}.people{grid-template-columns:1fr;gap:48px}.person img{aspect-ratio:4/4.6}.person figcaption{gap:10px}.person strong{font-size:27px}.person span{font-size:12px}.team-tail{display:block;margin-top:40px}.team-tail .text-link{margin-top:15px}.final-head{display:block}.final-head .eyebrow{margin-bottom:40px}.final h2{font-size:clamp(56px,12vw,86px);margin:0 0 38px}.final-bottom{display:block}.final p{font-size:17px;margin-bottom:28px}.final-link{gap:24px;width:100%}.footer{padding:64px 0 28px}.footer-upper{grid-template-columns:1fr 1fr;gap:34px 20px;padding-bottom:60px}.footer-brand{grid-column:1/3;margin-bottom:22px}.footer-brand img{width:183px}.footer-col:last-child{grid-column:1/3}.footer-col:last-child a{display:block;margin-right:0}.footer-meta{display:block;font-size:10px}.footer-meta span{display:block;margin-top:9px}}
@media(max-width:360px){:root{--pad:18px}.hero h1{font-size:clamp(49px,13vw,59px)}.hero-actions{gap:10px}.btn-primary{gap:8px}.hero-photo{height:290px}.photo-index strong{max-width:155px}.service-card h3{font-size:39px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
